css:
.govacct-sim-container {
    padding: 28px;
    background: #f4f6f8;
    min-height: 100vh;
    font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
    color: #1a2744;
}
.govacct-sim-header {
    background: linear-gradient(135deg, #1a2744 0%, #2a3f65 100%);
    color: #ffffff;
    padding: 32px 36px 28px;
    border-radius: 4px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.govacct-sim-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0; bottom: 0;
    width: 180px;
    background: linear-gradient(135deg, rgba(37,99,235,0.15) 0%, rgba(5,150,105,0.1) 100%);
}
.govacct-sim-header-badge {
    display: inline-block;
    background: rgba(255,255,255,0.15);
    border: 1px solid rgba(255,255,255,0.25);
    padding: 4px 14px;
    border-radius: 3px;
    font-size: 0.65rem;
    font-weight: 700;
    letter-spacing: 0.15em;
    text-transform: uppercase;
    margin-bottom: 12px;
    color: #93c5fd;
}
.govacct-sim-header h1 {
    font-size: 1.65rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: -0.01em;
}
.govacct-sim-subtitle {
    font-size: 0.9rem;
    color: #94a3b8;
    margin: 0;
    font-weight: 400;
}
.govacct-sim-period-counter {
    text-align: center;
    font-size: 0.85rem;
    color: #64748b;
    margin-bottom: 20px;
    font-weight: 500;
}
.govacct-sim-period-counter span {
    margin: 0 3px;
}
.govacct-sim-period-counter span:nth-child(2),
.govacct-sim-period-counter span:nth-child(4) {
    font-weight: 700;
    color: #1a2744;
    font-size: 1rem;
}
.govacct-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.govacct-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 18px 16px;
    position: relative;
    transition: box-shadow 0.2s ease;
}
.govacct-sim-kpi-card:hover {
    box-shadow: 0 4px 16px rgba(26,39,68,0.08);
}
.govacct-sim-kpi-icon {
    font-size: 1.2rem;
    margin-bottom: 6px;
}
.govacct-sim-kpi-label {
    font-size: 0.68rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #64748b;
    margin-bottom: 6px;
}
.govacct-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #1a2744;
}
.govacct-sim-kpi-risk .govacct-sim-kpi-value {
    color: #dc2626;
}
.govacct-sim-kpi-patrimonio .govacct-sim-kpi-value {
    color: #059669;
}
.govacct-sim-briefing {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-left: 4px solid #2563eb;
    border-radius: 4px;
    margin-bottom: 24px;
    overflow: hidden;
}
.govacct-sim-briefing-header {
    background: #f8fafc;
    padding: 14px 20px;
    border-bottom: 1px solid #e2e8f0;
}
.govacct-sim-briefing-header h3 {
    margin: 0;
    font-size: 0.95rem;
    font-weight: 700;
    color: #2563eb;
}
.govacct-sim-briefing-body {
    padding: 18px 20px;
    font-size: 0.88rem;
    line-height: 1.65;
    color: #334155;
}
.govacct-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.govacct-sim-controls h3 {
    font-size: 0.95rem;
    font-weight: 700;
    color: #1a2744;
    margin: 0 0 18px 0;
    padding-bottom: 10px;
    border-bottom: 2px solid #e2e8f0;
}
.govacct-sim-input-group {
    margin-bottom: 18px;
}
.govacct-sim-input-group label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #475569;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.govacct-sim-input-group input[type="number"],
.govacct-sim-input-group select {
    width: 100%;
    padding: 10px 14px;
    border: 1px solid #cbd5e1;
    border-radius: 4px;
    font-size: 0.92rem;
    color: #1a2744;
    background: #f8fafc;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.govacct-sim-input-group input[type="number"]:focus,
.govacct-sim-input-group select:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37,99,235,0.12);
    background: #ffffff;
}
.govacct-sim-input-group small {
    display: block;
    font-size: 0.75rem;
    color: #94a3b8;
    margin-top: 5px;
    font-style: italic;
}
.govacct-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 20px;
}
.govacct-sim-submit-btn {
    background: #2563eb;
    border-color: #2563eb;
    padding: 10px 28px;
    font-weight: 600;
    font-size: 0.9rem;
    letter-spacing: 0.02em;
    border-radius: 4px;
    transition: background 0.2s ease;
}
.govacct-sim-submit-btn:hover {
    background: #1d4ed8;
    border-color: #1d4ed8;
}
.govacct-sim-undo-btn {
    border-radius: 4px;
    font-size: 0.8rem;
}
.govacct-sim-chart-section {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.govacct-sim-chart-section h3 {
    font-size: 0.85rem;
    font-weight: 700;
    color: #64748b;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin: 0 0 16px 0;
}
.govacct-sim-chart-section canvas {
    max-height: 320px;
}
.govacct-sim-history {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 4px;
    padding: 20px;
}
.govacct-sim-history table {
    font-size: 0.82rem;
}
.govacct-sim-history thead th {
    background: #f8fafc;
    color: #475569;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.06em;
    border-bottom: 2px solid #e2e8f0;
    padding: 10px 12px;
}
.govacct-sim-history tbody td {
    padding: 8px 12px;
    color: #334155;
    border-bottom: 1px solid #f1f5f9;
}
@media (max-width: 768px) {
    .govacct-sim-container {
        padding: 14px;
    }
    .govacct-sim-header {
        padding: 20px;
    }
    .govacct-sim-header h1 {
        font-size: 1.2rem;
    }
    .govacct-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .govacct-sim-kpi-value {
        font-size: 1.3rem;
    }
    .govacct-sim-btn-row {
        flex-direction: column;
    }
    .govacct-sim-submit-btn {
        width: 100%;
    }
}

