(function() {
    'use strict';

    class GovAccountingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Contabilidad Gubernamental';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    titleFallback: 'Fase 1: Evaluación y Mapeo de Brechas CHIP',
                    descKey: 'r1_desc',
                    descFallback: 'Hospital San Roberto (ESE nivel III, Cali) debe adoptar el CHIP antes de septiembre 2025. Se han identificado 5 conflictos entre los requisitos de CHIP y la realidad operativa de la entidad.<br><br><strong>Presupuesto de implementación disponible:</strong> COP 180 millones.<br><strong>Ingresos devengados no reconocidos:</strong> COP 29.6 mil millones.<br><strong>Activos fijos sin depreciación sistemática:</strong> COP 56.1 mil millones.<br><strong>Provisiones no registradas:</strong> COP 20.27 mil millones.<br><br>Asigne recursos para la evaluación inicial y seleccione el área de enfoque prioritario para el equipo de transición.',
                    inputPanel: 'round1Inputs'
                },
                {
                    titleKey: 'r2_title',
                    titleFallback: 'Fase 2: Estrategia de Provisiones y Modernización',
                    descKey: 'r2_desc',
                    descFallback: 'La evaluación ha revelado la magnitud de los ajustes requeridos. Ahora debe definir la estrategia de reconocimiento de provisiones y la inversión en tecnología para el nuevo ciclo de cierre contable.<br><br><strong>Provisiones requeridas bajo CHIP:</strong><br>• Sentencias laborales confirmadas: COP 2.4B (certidumbre 100%)<br>• Demandas laborales estimadas: COP 2.17B (certidumbre 70%)<br>• Obligación de pensiones actuarial: COP 14.5B<br>• Multa + remediación ambiental: COP 1.2B<br><br><strong>Ciclo de cierre actual:</strong> 15 días. <strong>Requerido por CHIP:</strong> 60 días.',
                    inputPanel: 'round2Inputs'
                },
                {
                    titleKey: 'r3_title',
                    titleFallback: 'Fase 3: Construcción del Reporte Integrado CHIP',
                    descKey: 'r3_desc',
                    descFallback: 'Debe construir el primer reporte integrado CHIP de Hospital San Roberto para septiembre 2025. Determine las provisiones a reconocer y la política de depreciación.<br><br><strong>Patrimonio neto actual:</strong> ajustado según decisiones previas.<br><strong>Umbral regulatorio:</strong> si el patrimonio cae por debajo de COP 10B, la Superintendencia de Salud podría cuestionar la solvencia de HSR y activar intervención.<br><br>Bajo IPSAS 37, las sentencias ejecutoriadas (COP 2.4B) y la multa ambiental (COP 0.42B) son obligaciones ciertas que deben provisionarse. Diferir estas genera incumplimiento regulatorio.',
                    inputPanel: 'round3Inputs'
                },
                {
                    titleKey: 'r4_title',
                    titleFallback: 'Fase 4: Comunicación a Stakeholders y Plan de Implementación',
                    descKey: 'r4_desc',
                    descFallback: 'El reporte CHIP inicial está construido. Debe presentarlo al Consejo Directivo (Gobernador del Valle, Secretario de Salud) y a la Superintendencia de Salud, y definir la estrategia para cumplir con la fecha límite del 15 de octubre.<br><br><strong>Audiencias:</strong><br>• Consejo Directivo: espera demostrar que HSR está financieramente saludable.<br>• Superintendencia de Salud: exige reporte completo, oportuno y auditado.<br>• Medios y opinión pública: podrían malinterpretar los cambios en cifras como evidencia de problemas financieros.<br><br>El cambio de COP 2.8B de superávit (NGAIP 2024) a cifras CHIP requiere explicación cuidadosa.',
                    inputPanel: 'round4Inputs'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 180,
                    complianceScore: 20,
                    regulatoryRisk: 75,
                    stakeholderTrust: 50,
                    patrimonioNet: 28.0,
                    provisionsRecognized: 0,
                    depreciationApplied: 0,
                    closingCycleReady: false,
                    focusBonus: '',
                    complianceHistory: [],
                    riskHistory: [],
                    trustHistory: [],
                    budgetHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    mainValue: 60,
                    strategyChoice: 'phased'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) {
                var titleText = round.titleFallback;
                try { titleText = window.mySimulation.t(round.titleKey) || round.titleFallback; } catch(e) {}
                titleEl.innerHTML = titleText;
            }

            var bodyEl = document.getElementById('briefingText');
            if (bodyEl) {
                var descText = round.descFallback;
                try { descText = window.mySimulation.t(round.descKey) || round.descFallback; } catch(e) {}
                bodyEl.innerHTML = descText;
            }

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].inputPanel);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }
        }

        validateDecisions(decisions) {
            this._updateBriefing(window.mySimulation.state);
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var inv = document.getElementById('assessmentInvestment');
                if (inv) decisions.mainValue = parseFloat(inv.value);
                var focus = document.getElementById('focusArea');
                if (focus) decisions.strategyChoice = focus.value;

                if (!decisions.mainValue || decisions.mainValue < 40 || decisions.mainValue > 120) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_investment'), 'warning'
                    );
                    return false;
                }
                if (decisions.mainValue > window.mySimulation.state.domainState.budget) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_budget'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var approach = document.getElementById('provisionApproach');
                if (approach) decisions.strategyChoice = approach.value;
                var tech = document.getElementById('techBudget');
                if (tech) decisions.mainValue = parseFloat(tech.value);

                if (!decisions.mainValue || decisions.mainValue < 30 || decisions.mainValue > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_tech_budget'), 'warning'
                    );
                    return false;
                }
                if (decisions.mainValue > window.mySimulation.state.domainState.budget) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_budget'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var prov = document.getElementById('provisionAmount');
                if (prov) decisions.mainValue = parseFloat(prov.value);
                var depr = document.getElementById('depreciationPolicy');
                if (depr) decisions.strategyChoice = depr.value;

                if (decisions.mainValue === null || decisions.mainValue === undefined || decisions.mainValue < 0 || decisions.mainValue > 20.27) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_provision'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var transp = document.getElementById('transparencyLevel');
                if (transp) decisions.strategyChoice = transp.value;
                var deadline = document.getElementById('deadlineStrategy');
                if (deadline) decisions.mainValue = deadline.value;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var compDelta = 0;
            var riskDelta = 0;
            var trustDelta = 0;
            var budgetSpent = 0;
            var patrimonioDelta = 0;
            var phaseLabel = '';
            var insight = '';

            if (period === 1) {
                budgetSpent = d.mainValue;
                ds.budget -= budgetSpent;
                var investRatio = (d.mainValue - 40) / 80;
                compDelta = Math.round(10 + investRatio * 15);
                riskDelta = -1 * Math.round(5 + investRatio * 10);
                trustDelta = Math.round(3 + investRatio * 7);
                ds.focusBonus = d.strategyChoice;
                phaseLabel = 'Assessment';

                if (d.mainValue >= 80) {
                    insight = window.mySimulation.t('insight_r1_high');
                } else if (d.mainValue >= 60) {
                    insight = window.mySimulation.t('insight_r1_mid');
                } else {
                    insight = window.mySimulation.t('insight_r1_low');
                }
            } else if (period === 2) {
                budgetSpent = d.mainValue;
                ds.budget -= budgetSpent;

                if (d.strategyChoice === 'full') {
                    compDelta = 20;
                    riskDelta = -20;
                    trustDelta = 8;
                    if (ds.focusBonus === 'provisions') { compDelta += 5; }
                } else if (d.strategyChoice === 'phased') {
                    compDelta = 15;
                    riskDelta = -10;
                    trustDelta = 12;
                    if (ds.focusBonus === 'provisions') { compDelta += 3; }
                } else {
                    compDelta = 5;
                    riskDelta = 10;
                    trustDelta = -5;
                }

                if (d.mainValue >= 60) {
                    ds.closingCycleReady = true;
                    compDelta += 5;
                    riskDelta -= 5;
                    insight = window.mySimulation.t('insight_r2_techok');
                } else {
                    ds.closingCycleReady = false;
                    riskDelta += 8;
                    insight = window.mySimulation.t('insight_r2_techlow');
                }
                phaseLabel = 'Strategy';
            } else if (period === 3) {
                var provAmt = d.mainValue;
                ds.provisionsRecognized = provAmt;
                patrimonioDelta = -1 * provAmt;

                if (provAmt >= 3.6) {
                    compDelta = 10;
                    riskDelta = -10;
                } else {
                    compDelta = 0;
                    riskDelta = 15;
                }
                if (provAmt >= 10) {
                    compDelta = 15;
                    riskDelta = -15;
                }
                if (provAmt >= 18) {
                    compDelta = 20;
                    riskDelta = -20;
                }
                if (ds.focusBonus === 'provisions') { compDelta += 3; }

                if (d.strategyChoice === 'full') {
                    compDelta += 10;
                    riskDelta -= 10;
                    ds.depreciationApplied = 4.56;
                    patrimonioDelta -= 4.56;
                } else if (d.strategyChoice === 'partial') {
                    compDelta += 5;
                    riskDelta -= 5;
                    ds.depreciationApplied = 2.28;
                    patrimonioDelta -= 2.28;
                } else {
                    riskDelta += 5;
                    ds.depreciationApplied = 0;
                }
                if (ds.focusBonus === 'assets') { compDelta += 3; }

                ds.patrimonioNet += patrimonioDelta;

                if (ds.patrimonioNet < 10) {
                    trustDelta = -10;
                    riskDelta += 5;
                    insight = window.mySimulation.t('insight_r3_solvency');
                } else if (provAmt >= 3.6) {
                    trustDelta = 5;
                    insight = window.mySimulation.t('insight_r3_compliant');
                } else {
                    trustDelta = -5;
                    insight = window.mySimulation.t('insight_r3_noncompliant');
                }
                phaseLabel = 'Report';
            } else if (period === 4) {
                if (d.strategyChoice === 'full') {
                    trustDelta = 20;
                    compDelta = 5;
                } else if (d.strategyChoice === 'selective') {
                    trustDelta = 5;
                    compDelta = 2;
                } else {
                    trustDelta = -10;
                    compDelta = -5;
                    riskDelta += 10;
                }

                var deadlineVal = d.mainValue;
                if (deadlineVal === 'extension') {
                    riskDelta -= 5;
                    compDelta += 5;
                    trustDelta += 3;
                } else if (deadlineVal === 'softclose') {
                    compDelta += 3;
                    if (ds.closingCycleReady) {
                        riskDelta -= 3;
                    } else {
                        riskDelta += 5;
                    }
                } else {
                    if (ds.closingCycleReady) {
                        compDelta += 8;
                        riskDelta -= 8;
                        trustDelta += 5;
                    } else {
                        riskDelta += 15;
                        trustDelta -= 8;
                    }
                }

                if (d.strategyChoice === 'full' && (deadlineVal === 'extension' || ds.closingCycleReady)) {
                    insight = window.mySimulation.t('insight_r4_excellent');
                } else if (d.strategyChoice === 'minimal') {
                    insight = window.mySimulation.t('insight_r4_poor');
                } else {
                    insight = window.mySimulation.t('insight_r4_moderate');
                }
                phaseLabel = 'Communication';
            }

            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + compDelta));
            ds.regulatoryRisk = Math.max(0, Math.min(100, ds.regulatoryRisk + riskDelta));
            ds.stakeholderTrust = Math.max(0, Math.min(100, ds.stakeholderTrust + trustDelta));

            ds.complianceHistory.push(ds.complianceScore);
            ds.riskHistory.push(ds.regulatoryRisk);
            ds.trustHistory.push(ds.stakeholderTrust);
            ds.budgetHistory.push(ds.budget);

            // v1.1.0 P0 FIX: render next round's briefing/panel synchronously.
            // Old setTimeout fired AFTER the framework incremented state.currentPeriod, so
            // (currentPeriod + 1) overshot by one and showed the wrong input PANEL (round N+2)
            // for rounds 2-4 — the correct panel stayed hidden and its inputs defaulted.
            // Called here pre-increment, currentPeriod is still N so (N + 1) is the next round.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });

            return {
                period: period,
                phaseLabel: phaseLabel,
                compliance: ds.complianceScore,
                risk: ds.regulatoryRisk,
                trust: ds.stakeholderTrust,
                budgetSpent: budgetSpent,
                budgetRemaining: ds.budget,
                patrimonioNet: Math.round(ds.patrimonioNet * 100) / 100,
                insight: insight
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('complianceDisplay', 'domainState.complianceScore',
                (v) => Math.round(v) + '%');
            uiManager.bind('riskDisplay', 'domainState.regulatoryRisk',
                (v) => Math.round(v) + '%');
            uiManager.bind('trustDisplay', 'domainState.stakeholderTrust',
                (v) => Math.round(v) + '%');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => Math.round(v).toLocaleString());
            uiManager.bind('patrimonioDisplay', 'domainState.patrimonioNet',
                (v) => (Math.round(v * 10) / 10).toFixed(1));

            // v1.1.0 FIX: framework Undo restores state/KPIs but not this sim's briefing/panel.
            // Re-render the restored round's panel (deferred, after the framework's undo handler).
            var self = this;
            var undoBtn = document.getElementById('undoBtn');
            if (undoBtn) {
                undoBtn.addEventListener('click', function() {
                    setTimeout(function() {
                        if (window.mySimulation && window.mySimulation.state) {
                            self._updateBriefing(window.mySimulation.state);
                        }
                    }, 0);
                });
            }
        }

        getChartConfig() {
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: t('chart_compliance'),
                                data: [],
                                borderColor: '#2563eb',
                                backgroundColor: 'rgba(37,99,235,0.08)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#2563eb'
                            },
                            {
                                label: t('chart_risk'),
                                data: [],
                                borderColor: '#dc2626',
                                backgroundColor: 'rgba(220,38,38,0.08)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#dc2626'
                            },
                            {
                                label: t('chart_trust'),
                                data: [],
                                borderColor: '#059669',
                                backgroundColor: 'rgba(5,150,105,0.08)',
                                borderWidth: 3,
                                fill: false,
                                tension: 0.2,
                                pointRadius: 5,
                                pointBackgroundColor: '#059669'
                            }
