        getChartData(state) {
            var labels = state.domainState.complianceHistory.map(function(_, i) { return 'F' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.complianceHistory },
                        { data: state.domainState.riskHistory },
                        { data: state.domainState.trustHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var compliance = last.results ? last.results.compliance : 0;
            var risk = last.results ? last.results.risk : 100;
            var trust = last.results ? last.results.trust : 0;
            var patrimonio = last.results ? last.results.patrimonioNet : 28;

            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var score = compliance + trust + (100 - risk);
            var performance = t('perf_needs');
            if (score >= 220 && compliance >= 80 && risk <= 30) performance = t('perf_excellent');
            else if (score >= 170 && compliance >= 60) performance = t('perf_good');
            else if (score >= 130) performance = t('perf_acceptable');

            var insights = [];
            if (compliance >= 80) insights.push(t('insight_comp_high'));
            else if (compliance >= 60) insights.push(t('insight_comp_mid'));
            else insights.push(t('insight_comp_low'));

            if (risk <= 30) insights.push(t('insight_risk_low'));
            else if (risk > 60) insights.push(t('insight_risk_high'));

            if (patrimonio < 10) insights.push(t('insight_solvency'));
            if (trust >= 75) insights.push(t('insight_trust_high'));

            return {
                finalCompliance: compliance,
                finalRisk: risk,
                finalTrust: trust,
                finalPatrimonio: patrimonio,
                compositeScore: score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results && results.insight) return results.insight;
            return null;
        }

